-- migration_101_speaking_tests.sql  (2026-11-05)
-- IELTS Speaking tests in the website.
--   * speaking_sets: one full test per row (Part 1 topics and questions,
--     the Part 2 cue card and rounding-off question, Part 3 discussion),
--     with Band 8 model answers, phrases and grammar for each question.
--     Teachers add more from the Practice Bank ("New speaking set").
--   * Every set shows in the Practice Bank as four pages: the full test,
--     Part 1, Part 2 and Part 3 (kept in step by a trigger), so it is
--     given as homework like any other page. Speaking stays homework-only:
--     never on the students' shelf.
--   * speaking-voice: the examiner's recorded questions (made once per
--     question by the ai-grading function, then reused).
--   * save_speaking_feedback(): the ai-grading function saves the AI band
--     and feedback on the student's homework attempt.
--   * Set 8 (Landscapes · Countryside · Services) is added.
-- Safe to run twice. Needs migrations 84, 85 and 92 first.

-- 1. Sets ------------------------------------------------------------
create table if not exists public.speaking_sets (
  id uuid primary key default gen_random_uuid(),
  number integer not null,
  title text not null,
  topics text not null default '',
  content jsonb not null,
  created_by uuid references public.profiles(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists speaking_sets_number_key on public.speaking_sets (number);

alter table public.speaking_sets enable row level security;
drop policy if exists speaking_sets_read on public.speaking_sets;
create policy speaking_sets_read on public.speaking_sets
  for select to authenticated using (true);
drop policy if exists speaking_sets_teacher_write on public.speaking_sets;
create policy speaking_sets_teacher_write on public.speaking_sets
  for all using ((select public.is_teacher())) with check ((select public.is_teacher()));

-- 2. Practice Bank pages for each set ---------------------------------
alter table public.materials drop constraint if exists materials_skill_check;
alter table public.materials
  add constraint materials_skill_check check (skill is null or skill in ('reading', 'listening', 'writing', 'workshop', 'speaking'));

create or replace function public.speaking_set_pages()
returns trigger
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_p1 text;
  v_p2 text;
  v_p3 text;
begin
  if tg_op = 'DELETE' then
    delete from public.materials where storage_path like 'speaking:' || old.id || '#%';
    return old;
  end if;

  select string_agg(t->>'topic', ' · ') into v_p1 from jsonb_array_elements(coalesce(new.content->'part1', '[]'::jsonb)) t;
  v_p2 := coalesce(new.content#>>'{part2,cue}', 'Cue card');
  v_p3 := coalesce(nullif(new.content#>>'{part3,title}', ''), initcap(coalesce(nullif(new.content#>>'{part3,theme}', ''), 'Discussion')));

  insert into public.materials
    (title, file_name, storage_path, url, mime_type, size_bytes, source,
     skill, question_type, collection, position, on_shelf, created_by)
  values
    ('Set ' || new.number || ': ' || coalesce(nullif(new.topics, ''), new.title), new.title, 'speaking:' || new.id || '#full', 'speaking:' || new.id || '#full', 'application/json', 0, 'upload', 'speaking', 'speaking_full', 'Speaking Tests · Full tests', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || coalesce(v_p1, 'Part 1'), new.title, 'speaking:' || new.id || '#part1', 'speaking:' || new.id || '#part1', 'application/json', 0, 'upload', 'speaking', 'speaking_part1', 'Speaking Tests · Part 1', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p2, new.title, 'speaking:' || new.id || '#part2', 'speaking:' || new.id || '#part2', 'application/json', 0, 'upload', 'speaking', 'speaking_part2', 'Speaking Tests · Part 2', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p3, new.title, 'speaking:' || new.id || '#part3', 'speaking:' || new.id || '#part3', 'application/json', 0, 'upload', 'speaking', 'speaking_part3', 'Speaking Tests · Part 3', new.number, false, new.created_by)
  on conflict (storage_path) do update
    set title = excluded.title, file_name = excluded.file_name, position = excluded.position;
  return new;
end;
$function$;

drop trigger if exists trg_speaking_set_pages on public.speaking_sets;
create trigger trg_speaking_set_pages
  after insert or update of number, title, topics, content or delete on public.speaking_sets
  for each row execute function public.speaking_set_pages();

-- 3. The examiner's voice (public, read-only for everyone) ------------
insert into storage.buckets (id, name, public)
values ('speaking-voice', 'speaking-voice', true)
on conflict (id) do update set public = true;

-- 4. AI feedback on a speaking homework attempt -----------------------
create or replace function public.save_speaking_feedback(p_attempt_id uuid, p_band numeric, p_ai jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $function$
begin
  perform set_config('app.homework_grading', 'on', true);
  update public.homework_attempts
     set band = coalesce(p_band, band),
         results = coalesce(results, '{}'::jsonb) || jsonb_build_object('ai', p_ai)
   where id = p_attempt_id;
  perform set_config('app.homework_grading', 'off', true);
end;
$function$;

revoke all on function public.save_speaking_feedback(uuid, numeric, jsonb) from public, anon, authenticated;
grant execute on function public.save_speaking_feedback(uuid, numeric, jsonb) to service_role;

-- 5. Set 8 ------------------------------------------------------------
insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0001-0000-4000-8000-000000000008', 8, 'Set 8', 'Landscapes · Countryside · Services', '{"period": "September 2026 – April 2027", "part1": [{"topic": "Landscapes", "intro": "Now, in this first part, I’d like to ask you some questions about yourself. Let’s talk about landscapes.", "questions": [{"q": "What kinds of landscapes are common in your country?", "model": {"answer": "We have a bit of everything. There are vast deserts in the west, rolling green hills in the south, and snow-capped mountains in the east. The diversity of scenery is one of the things I love most about the place.", "phrases": [["vast", "extremely large in area"], ["rolling (hills)", "gently rising and falling"], ["snow-capped", "covered with snow on top"]], "grammar": [{"pattern": "a bit of everything", "use": "have a bit of everything: a wide variety", "example": "We have a bit of everything", "try": "The city has a bit of ______."}, {"pattern": "one of the things I + verb", "use": "one of the things I love most about + noun", "example": "one of the things I love most about the place", "try": "One of the things I love most about ______ is ______."}]}}, {"q": "Do you think landscapes are important for tourism?", "model": {"answer": "Definitely. Stunning scenery is a major draw for visitors, and many tourists travel specifically to take in the views. Places with breathtaking landscapes can boost the local economy enormously, as hotels and restaurants spring up to serve them.", "phrases": [["a draw", "something that attracts people"], ["take in the views", "look at and enjoy the scenery"], ["boost the local economy", "help the area’s businesses and income grow"]], "grammar": [{"pattern": "travel specifically to + verb", "use": "travel specifically to + base verb: for one purpose", "example": "many tourists travel specifically to take in the views", "try": "People travel specifically to ______."}, {"pattern": "as + clause", "use": "as + clause: because, in the situation that", "example": "as hotels and restaurants spring up to serve them", "try": "…, as ______."}]}}, {"q": "Do you enjoy taking photos of landscapes?", "model": {"answer": "I do, though I’m just an amateur. I love getting up early to capture the golden light on the hills. A good landscape shot takes my breath away even on my phone, and I like to frame my shots carefully.", "phrases": [["capture", "record in a photo"], ["the golden light", "warm, soft light at sunrise or sunset"], ["take someone’s breath away", "impress someone greatly"]], "grammar": [{"pattern": "love + -ing", "use": "love + -ing: enjoy an activity", "example": "I love getting up early to capture the golden light", "try": "I love ______ing."}, {"pattern": "even on + noun", "use": "even on + noun: surprisingly, in poor conditions too", "example": "even on my phone", "try": "…, even on ______."}]}}, {"q": "What views can you see from the windows of your home?", "model": {"answer": "From my bedroom, I can see a small park with tall poplar trees, and beyond it, the skyline of the city. It’s not exactly picture-perfect, but watching the sunset from my window is a daily treat.", "phrases": [["tall poplar trees", "very high trees common in Central Asia"], ["skyline", "the outline of buildings against the sky"], ["picture-perfect", "so beautiful it looks like a picture"]], "grammar": [{"pattern": "From + place, I can see", "use": "From + place, I can see + noun: describing a view", "example": "From my bedroom, I can see a small park", "try": "From my window, I can see ______."}, {"pattern": "watching … is + noun", "use": "-ing phrase as subject + is + noun", "example": "watching the sunset from my window is a daily treat", "try": "Watching ______ is ______."}]}}]}, {"topic": "Countryside", "intro": "Now let’s move on to talk about the countryside.", "questions": [{"q": "Do you often visit the countryside?", "model": {"answer": "Not as often as I’d like. I usually head out to my grandparents’ village once or twice a month, mainly to get away from it all. It’s a welcome break from the noise of the city.", "phrases": [["head out", "leave to go somewhere"], ["get away from it all", "escape from busy daily life"], ["a welcome break", "a rest that you are pleased to have"]], "grammar": [{"pattern": "not as often as I’d like", "use": "not as + adverb + as I’d like: wishing for more", "example": "Not as often as I’d like", "try": "Not as ______ as I’d like."}, {"pattern": "once or twice a month", "use": "once or twice + a + period: frequency", "example": "once or twice a month", "try": "I go once or twice a ______."}]}}, {"q": "Why is the country more peaceful?", "model": {"answer": "Mainly because there’s far less traffic and fewer people. You can hear the birds instead of honking horns, and the pace of life is much slower. It’s the perfect place to recharge your batteries and unwind.", "phrases": [["honking horns", "loud car warning sounds"], ["the pace of life", "how fast or slow daily life feels"], ["recharge your batteries", "rest to regain energy"]], "grammar": [{"pattern": "far less + uncountable / fewer +", "use": "plural far less traffic, fewer people", "example": "far less traffic and fewer people", "try": "There’s far less ______ and fewer ______."}, {"pattern": "instead of + noun", "use": "instead of + noun: in place of", "example": "instead of honking horns", "try": "You can hear ______ instead of ______."}]}}, {"q": "Is there anything interesting in the countryside?", "model": {"answer": "Plenty. There are orchards where you can pick fruit straight from the tree, and traditional farmsteads that offer a glimpse of rural life. I also love stargazing, because the sky is so much clearer without city lights.", "phrases": [["an orchard", "a place where fruit trees grow"], ["pick fruit", "collect fruit from trees"], ["rural life", "the way of life in the countryside"]], "grammar": [{"pattern": "where + clause", "use": "noun + where + clause: a place relative clause", "example": "orchards where you can pick fruit straight from the tree", "try": "places where you can ______."}, {"pattern": "so much + comparative", "use": "so much + comparative: a big difference", "example": "the sky is so much clearer without city lights", "try": "It’s so much ______ than in the city."}]}}, {"q": "Would you like to live in the countryside in the future?", "model": {"answer": "Perhaps when I retire. At the moment, I’m too attached to city life and the career opportunities it offers. But eventually I’d love to settle down somewhere quiet with a garden and live off the land.", "phrases": [["be attached to", "feel affection for or reliant on something"], ["settle down", "start a stable life in one place"], ["live off the land", "produce your own food from nature"]], "grammar": [{"pattern": "too + adjective + to", "use": "too attached to city life: an obstacle", "example": "I’m too attached to city life", "try": "I’m too ______ to ______."}, {"pattern": "I’d love to + base verb", "use": "I’d love to + base verb: a wish", "example": "I’d love to settle down somewhere quiet", "try": "I’d love to ______."}]}}]}], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say, and you can make some notes if you wish. Do you understand? Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe… All right? Remember, you have one to two minutes for this, so don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?", "rounding": {"q": "Do you often leave feedback after receiving a service?", "model": {"answer": "Yes, if it’s particularly good or bad. A short online review can really make a difference to a small business.", "phrases": [], "grammar": []}}, "cue": "Describe a good service that you received", "bullets": ["what the service was", "where you received it", "who provided the service"], "explain": "and explain why you thought it was good.", "notes": ["What it was", "Where", "Who provided it", "Why it was good"], "tip": "Speaking time: aim for 1:30–2:00. Spend about 20 seconds on what, 15 on where, 20 on who, and keep the most time for why it was good.", "model": {"answer": "I’d like to talk about the repair service I received when my laptop broke down just before an important deadline. I had a sinking feeling that I’d lose all my work, so I was in a bit of a panic. I took it to a small repair shop in the city centre, which a friend had recommended. It’s a family-run business that’s been around for years, and it has a loyal customer base. The technician who helped me was a young man called Timur. He was polite and down-to-earth, and he took the time to explain the problem in plain language, rather than blinding me with jargon. I thought the service was top-notch for several reasons. Firstly, he went above and beyond, fixing the laptop the same afternoon, even though he was swamped with other jobs. Secondly, he charged a fair price and didn’t try to upsell me anything I didn’t need. And finally, he followed up the next day to check that everything was working. That kind of attention to detail made me feel valued, and I’ve recommended the shop to everyone since.", "sections": [{"label": "What it was", "text": "I’d like to talk about the repair service I received when my laptop broke down just before an important deadline. I had a sinking feeling that I’d lose all my work, so I was in a bit of a panic."}, {"label": "Where", "text": "I took it to a small repair shop in the city centre, which a friend had recommended. It’s a family-run business that’s been around for years, and it has a loyal customer base."}, {"label": "Who provided it", "text": "The technician who helped me was a young man called Timur. He was polite and down-to-earth, and he took the time to explain the problem in plain language, rather than blinding me with jargon."}, {"label": "Why it was good", "text": "I thought the service was top-notch for several reasons. Firstly, he went above and beyond, fixing the laptop the same afternoon, even though he was swamped with other jobs. Secondly, he charged a fair price and didn’t try to upsell me anything I didn’t need. And finally, he followed up the next day to check that everything was working. That kind of attention to detail made me feel valued, and I’ve recommended the shop to everyone since."}], "phrases": [["a sinking feeling", "a sudden fear that something bad will happen"], ["family-run", "owned and managed by a family"], ["a loyal customer base", "regular customers who keep returning"], ["down-to-earth", "practical and friendly, not showing off"], ["take the time to", "make a special effort to do something"], ["blind (someone) with jargon", "confuse someone with technical words"], ["top-notch", "of the highest quality"], ["go above and beyond", "do much more than is expected"], ["be swamped with", "have too much work to do"], ["charge a fair price", "ask for a reasonable amount of money"], ["follow up", "contact someone later to check something"], ["attention to detail", "care about small points"]], "grammar": [{"pattern": "Past perfect for an earlier event", "use": "had + past participle: an event before another past event", "example": "which a friend had recommended", "try": "…, which my friend had ______."}, {"pattern": "a feeling that + clause", "use": "a feeling that + clause: a noun clause", "example": "I had a sinking feeling that I’d lose all my work", "try": "I had a feeling that ______."}, {"pattern": "rather than + -ing", "use": "rather than + -ing: instead of", "example": "rather than blinding me with jargon", "try": "…, rather than ______ing."}, {"pattern": "even though + clause", "use": "even though + clause: a surprising contrast", "example": "even though he was swamped with other jobs", "try": "…, even though ______."}, {"pattern": "didn’t try to + base verb", "use": "didn’t try to + base verb: did not attempt", "example": "didn’t try to upsell me anything I didn’t need", "try": "He didn’t try to ______."}, {"pattern": "Present perfect with since", "use": "I’ve + past participle + since: from then until now", "example": "I’ve recommended the shop to everyone since", "try": "I’ve ______ ever since."}], "why": ["It follows the cue-card bullets in order, so the examiner can follow it easily.", "A small story (a broken laptop before a deadline) makes the service feel real.", "The why paragraph is clearly organised with firstly, secondly, finally.", "It ends by linking the service to a result, which sounds natural and complete."]}}, "part3": {"questions": [{"q": "Why is customer service important?", "model": {"answer": "It’s the face of a company. Good service builds trust and customer loyalty, which brings in repeat business. Customers who feel valued are also more likely to spread the word, whereas one bad experience can tarnish a brand’s reputation very quickly.", "phrases": [["build trust", "make people believe in you"], ["customer loyalty", "the tendency of customers to keep returning"], ["repeat business", "sales from existing customers"], ["spread the word", "tell many people about something"], ["tarnish a reputation", "damage how people see you"], ["the face of a company", "the part that represents the whole business"]], "grammar": [{"pattern": "Customers who + verb", "use": "noun + who + verb: a defining relative clause", "example": "Customers who feel valued are also more likely to spread the word", "try": "Customers who ______ are more likely to ______."}, {"pattern": "whereas", "use": "clause, whereas + clause: a contrast", "example": "whereas one bad experience can tarnish a brand’s reputation very quickly", "try": "…, whereas ______."}]}}, {"q": "What makes a service good or bad?", "model": {"answer": "A good service is prompt, reliable and personalised. Staff should be knowledgeable and go the extra mile to solve problems. A bad service, on the other hand, is one where you’re kept waiting, passed from pillar to post, or brushed off by staff who don’t seem to care.", "phrases": [["prompt", "quick and on time"], ["reliable", "able to be trusted to do things well"], ["go the extra mile", "make more effort than required"], ["be kept waiting", "be made to wait"], ["pass from pillar to post", "be sent from one person to another without help"], ["brush off", "ignore or dismiss someone"]], "grammar": [{"pattern": "is one where", "use": "a service is one where + clause: a defining description", "example": "is one where you’re kept waiting", "try": "A bad service is one where ______."}, {"pattern": "by staff who", "use": "by + noun + who + verb: a passive agent with relative clause", "example": "brushed off by staff who don’t seem to care", "try": "…, by people who ______."}]}}, {"q": "If a company provided excellent products but poor customer service, would it be successful?", "model": {"answer": "In the short term, perhaps, but it wouldn’t last long. Even cutting-edge products can’t make up for rude or unhelpful staff, because customers will simply take their business elsewhere. In a competitive market, after-sales support often tips the balance.", "phrases": [["last long", "remain successful for a long time"], ["cutting-edge", "using the newest ideas or technology"], ["make up for", "compensate for something"], ["take your business elsewhere", "buy from another company"], ["a competitive market", "one with many rival companies"], ["tip the balance", "decide the outcome"]], "grammar": [{"pattern": "would + base verb", "use": "it wouldn’t + base verb: a hypothetical result", "example": "it wouldn’t last long", "try": "It wouldn’t ______."}, {"pattern": "Even + adjective + noun", "use": "even + adjective + noun + can’t: a strong concession", "example": "Even cutting-edge products can’t make up for rude or unhelpful staff", "try": "Even ______ can’t ______."}]}}, {"q": "Why do some people just be silent when they receive poor service?", "model": {"answer": "Some people simply avoid confrontation, and they’d rather grin and bear it than make a scene. Others think it’s not worth the hassle or fear that complaining won’t make any difference. Cultural factors play a part too, as in some societies it’s considered impolite to complain.", "phrases": [["avoid confrontation", "stay away from arguments"], ["grin and bear it", "accept something unpleasant without complaining"], ["make a scene", "behave in a loud, embarrassing way"], ["not worth the hassle", "too much trouble to be worth doing"], ["make any difference", "change the situation"], ["it’s impolite to complain", "complaining is seen as rude"]], "grammar": [{"pattern": "would rather + base verb + than", "use": "would rather + base verb + than + base verb: a preference", "example": "they’d rather grin and bear it than make a scene", "try": "They’d rather ______ than ______."}, {"pattern": "it’s considered + adjective + to", "use": "it’s considered + adjective + to + verb: a general view", "example": "it’s considered impolite to complain", "try": "It’s considered ______ to ______."}]}}, {"q": "How do you think customer service will change in the future?", "model": {"answer": "I expect automation to play a much bigger role. Chatbots already handle routine queries around the clock, and AI will become better at personalising the experience. However, I believe people will still crave a human touch when dealing with complicated issues.", "phrases": [["automation", "use of machines instead of people"], ["chatbot", "a program that chats with customers"], ["handle routine queries", "deal with common questions"], ["personalise", "tailor to an individual"], ["crave", "want very much"], ["the human touch", "warmth and understanding from a real person"]], "grammar": [{"pattern": "expect + object + to", "use": "expect + noun + to + base verb: a prediction", "example": "I expect automation to play a much bigger role", "try": "I expect ______ to ______."}, {"pattern": "will become + comparative", "use": "will become + comparative + at + -ing: future change", "example": "AI will become better at personalising the experience", "try": "AI will become better at ______ing."}]}}], "intro": "We’ve been talking about a good service that you received, and now I’d like to discuss with you one or two general questions related to this. Let’s consider customer service.", "theme": "customer service", "closing": "Thank you. That is the end of the speaking test."}}'::jsonb, null)
